// The shared conformance cases (testdata/conformance/envelopes.json,
// generated by internal/conformance from real sealed envelopes). The Go
// relay's parser and this Worker must agree on every one.

import { beforeEach, describe, expect, it } from "vitest";
import cases from "../../testdata/conformance/envelopes.json";
import { parseEnvelope } from "../src/envelope";
import { call, poll, resetRelay, setClock, type Peer } from "./helpers";

interface Case {
  name: string;
  envelope_json: string;
  expect: "valid" | "invalid" | "too_large";
  canonical?: string;
}

const all = cases as Case[];
const bytes = (s: string) => new TextEncoder().encode(s);

describe("conformance fixture", () => {
  it("has every category", () => {
    const kinds = new Set(all.map((c) => c.expect));
    expect([...kinds].sort()).toEqual(["invalid", "too_large", "valid"]);
    expect(all.length).toBeGreaterThan(100);
  });

  describe.each(all)("parseEnvelope: $name", (c) => {
    it(`is ${c.expect}`, () => {
      const r = parseEnvelope(bytes(c.envelope_json));
      if (c.expect === "valid") {
        expect(r.ok).toBe(true);
        if (r.ok) expect(r.canonical).toBe(c.canonical);
      } else {
        expect(r).toEqual({ ok: false, error: c.expect });
      }
    });
  });
});

describe("conformance over HTTP", () => {
  beforeEach(resetRelay);

  // Invalid and oversize envelopes are refused before identity binding or
  // the replay window apply, whoever sends them.
  const refused = all.filter((c) => c.expect !== "valid");
  it.each(refused)("POST $name -> $expect", async (c) => {
    const r = await call("POST", "/v1/msg", { as: "peer-a", body: c.envelope_json });
    const want = c.expect === "too_large" ? [413, "too_large"] : [400, "invalid"];
    expect([r.status, r.body]).toEqual([want[0], JSON.stringify({ error: want[1] }) + "\n"]);
  });

  // Valid envelopes between the two configured peers, with the relay's
  // clock set to the fixture's ts, are stored and served canonically.
  const deliverable = all.filter((c) => {
    if (c.expect !== "valid") return false;
    const e = JSON.parse(c.canonical!) as { from: string; to: string; ts: number };
    return ["peer-a", "peer-b"].includes(e.from) && ["peer-a", "peer-b"].includes(e.to) && e.ts === 1793824000;
  });
  it("includes deliverable cases", () => expect(deliverable.length).toBeGreaterThan(5));
  it.each(deliverable)("POST $name -> 201, served canonically", async (c) => {
    const e = JSON.parse(c.canonical!) as { from: Peer; to: Peer; ts: number };
    await setClock(e.ts * 1000);
    const r = await call("POST", "/v1/msg", { as: e.from, body: c.envelope_json });
    expect(r.status).toBe(201);
    const p = await poll(e.to, e.to);
    expect(p.envelopes).toEqual([c.canonical]);
  });
});
